precision mediump float;

varying mediump vec2 v_texCoord;
varying lowp    vec4 v_color;

uniform sampler2D   s_texture;

void main()
{
	vec4 tex = texture2D( s_texture, v_texCoord );

	tex.rgb += v_color.rgb;
    tex.a *= v_color.a;

	gl_FragColor = tex;
}

