#ifndef FEATHER_WIDTH
#define FEATHER_WIDTH 0.5
#endif

#ifdef SHADER_DERIVATIVES_SUPPORTED

#extension GL_OES_standard_derivatives : require

precision mediump float;

varying   vec4  v_color;
varying   vec2  v_attribs;

void main()
{
    float feather = FEATHER_WIDTH * v_attribs.y;

    float khigh = 2.0 - feather;
    float klow  = feather; 

    float t = v_attribs.x + 1.0;

    float dt = fwidth(t);

    float low  = smoothstep (klow - dt, klow + dt, t);
    float high  = 1.0 - smoothstep (khigh - dt, khigh + dt, t);

    float alpha = low * high;

    gl_FragColor = vec4 (v_color.rgb, alpha * v_color.a);
}

#else

precision mediump float;

varying   vec4  v_color;
varying   vec2  v_attribs;

void main()
{
    float halfWidth = 0.5 / v_attribs.y;

    float t         = v_attribs.x * halfWidth;

    float s0        = halfWidth;
    float s1        = halfWidth - FEATHER_WIDTH;

    float u         = smoothstep (-s0, -s1, t);
    float v         = smoothstep ( s0,  s1, t);

    float alpha     = min (u, v);

	gl_FragColor    = vec4 (v_color.rgb, v_color.a * alpha);
}

#endif

